import json,pathlib,subprocess,hashlib,sys,os
def execute(manifest_path,output_path):
 manifest=json.loads(pathlib.Path(manifest_path).read_text(encoding="utf8"))
 items=manifest["sources"];assert items and len({i["path"] for i in items})==len(items)
 before={}
 for item in items:
  path=pathlib.Path(item["path"]);raw=path.read_bytes()
  assert hashlib.sha256(raw).hexdigest()==item["sha256"]
  before[str(path)]=raw
 def parse(paths):
  args=["ansible-inventory"]
  for p in paths:args+=["-i",p]
  r=subprocess.run(args+["--list"],capture_output=True,text=True,timeout=12)
  if r.returncode:raise ValueError("inventory source parsing failed")
  data=json.loads(r.stdout)
  return data.get("_meta",{}).get("hostvars",{})
 combined={}
 for item in items:
  result=parse([item["path"]])
  if not result:raise ValueError("individual source empty")
  for name,vars in result.items():
   identity={"address":vars.get("ansible_host"),"environment":vars.get("environment")}
   if not isinstance(identity["address"],str) or not identity["address"] or identity["environment"]!=manifest["environment"]:raise ValueError("invalid identity")
   if name in combined and combined[name]!=identity:raise ValueError("same alias has conflicting source identities")
   combined[name]=identity
 merged=parse([i["path"] for i in items])
 observed={name:{"address":v.get("ansible_host"),"environment":v.get("environment")} for name,v in merged.items()}
 assert observed==combined and combined
 assert all(pathlib.Path(name).read_bytes()==raw for name,raw in before.items())
 snapshot={"sources":[{"path":i["path"],"sha256":i["sha256"]} for i in items],"targets":[{"alias":n,**combined[n]} for n in sorted(combined)]}
 output=pathlib.Path(output_path);temporary=output.with_suffix(output.suffix+".new")
 temporary.write_text(json.dumps(snapshot,sort_keys=True),encoding="utf8");temporary.replace(output)
 return snapshot
if __name__=="__main__":execute(sys.argv[1],sys.argv[2])

```

