```python
import hashlib,json,os,pathlib,shutil,subprocess,sys,tarfile,tempfile
root=pathlib.Path.cwd()
manifest=json.loads((root/sys.argv[1]).read_text(encoding="utf8"))
entries=manifest["collections"]
if not isinstance(entries,list) or len(entries)!=2:raise ValueError("complete app/core closure required")
seen=set();archives=[]
for item in entries:
    if set(item)!={"name","version","file","sha256"}:raise ValueError("unexpected manifest fields")
    name=item["name"]
    if name not in {"lab.app","lab.core"} or name in seen:raise ValueError("unexpected or duplicate collection")
    seen.add(name)
    rel=pathlib.PurePosixPath(item["file"])
    if rel.is_absolute() or ".." in rel.parts or rel.parts[:1]!=("vendor",):raise ValueError("archive outside vendor")
    archive=(root/pathlib.Path(*rel.parts)).resolve()
    if not archive.is_relative_to((root/"vendor").resolve()):raise ValueError("archive escaped vendor")
    if hashlib.sha256(archive.read_bytes()).hexdigest()!=item["sha256"]:raise ValueError("checksum mismatch")
    with tarfile.open(archive,"r:gz") as package:
        metadata=json.load(package.extractfile("MANIFEST.json"))["collection_info"]
    if metadata["namespace"]+"."+metadata["name"]!=name or metadata["version"]!=item["version"]:raise ValueError("manifest does not describe actual archive")
    archives.append(archive)
if seen!={"lab.app","lab.core"}:raise ValueError("missing dependency")
active=root/"active"
if not active.is_dir() or (root/"previous").exists():raise ValueError("unexpected current generation")
with tempfile.TemporaryDirectory(prefix="bundle-stage-",dir=root) as tmp:
    stage=pathlib.Path(tmp);collections=stage/"collections"
    requirements=stage/"requirements.json"
    requirements.write_text(json.dumps({"collections":[{"name":str(p),"type":"file"} for p in archives]}),encoding="utf8")
    env={k:v for k,v in os.environ.items() if not k.startswith("ANSIBLE_")}
    env.update(ANSIBLE_COLLECTIONS_PATH=str(collections),ANSIBLE_COLLECTIONS_SCAN_SYS_PATH="false",ANSIBLE_NOCOLOR="1",ANSIBLE_LOCAL_TEMP=str(stage/"ctrl"),ANSIBLE_REMOTE_TEMP=str(stage/"remote"),HOME=str(stage/"home"))
    config=stage/"ansible.cfg";config.write_text("[defaults]\nretry_files_enabled=False\n",encoding="utf8");env["ANSIBLE_CONFIG"]=str(config)
    def run(args):
        subprocess.run(args,cwd=root,env=env,check=True,capture_output=True,text=True,timeout=25)
    run(["ansible-galaxy","collection","install","-r",str(requirements),"--offline","-p",str(collections)])
    for item in entries:
        ns,name=item["name"].split(".")
        installed=json.loads((collections/"ansible_collections"/ns/name/"MANIFEST.json").read_text())
        if installed["collection_info"]["version"]!=item["version"]:raise ValueError("installed version mismatch")
    output=stage/"probe.txt";values=stage/"vars.json"
    values.write_text(json.dumps({"output_file":str(output),"input_text":" hello ","ansible_python_interpreter":sys.executable}),encoding="utf8")
    run(["ansible-playbook","-i","localhost,",str(root/"smoke.yaml"),"-f","1","-e","@"+str(values)])
    if output.read_text()!="app2:HELLO":raise ValueError("staged runtime behavior rejected")
    backup=root/"previous"
    os.replace(active,backup)
    try:os.replace(collections,active)
    except BaseException:
        os.replace(backup,active)
        raise
    shutil.rmtree(backup)

