p=argparse.ArgumentParser();p.add_argument("--input",required=True);p.add_argument("--output",required=True);p.add_argument("--run-id",required=True);a=p.parse_args()
if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_-]{0,39}",a.run_id):raise SystemExit("invalid run id")
source=pathlib.Path(a.input).resolve();out=pathlib.Path(a.output).resolve();run=out/a.run_id
run.mkdir(parents=True,exist_ok=False)
names=["playbook.yaml","inventory.json","variables.json"]
for name in names:shutil.copyfile(source/name,run/name)
(run/"ansible.cfg").write_text("[defaults]\nretry_files_enabled=False\n",encoding="utf8")
before={name:hashlib.sha256((run/name).read_bytes()).hexdigest() for name in names}
env={k:v for k,v in os.environ.items() if not k.startswith("ANSIBLE_")}
env.update(ANSIBLE_CONFIG=str(run/"ansible.cfg"),ANSIBLE_NOCOLOR="1",ANSIBLE_LOCAL_TEMP=str(run/"ctrl"),ANSIBLE_REMOTE_TEMP=str(run/"remote"))
args=["ansible-playbook","-i","inventory.json","playbook.yaml","-e","@variables.json","-f","1"]
start=datetime.datetime.now(datetime.timezone.utc).isoformat()
result=subprocess.run(args,cwd=run,env=env,capture_output=True,text=True,timeout=30)
(run/"stdout.log").write_text(result.stdout,encoding="utf8");(run/"stderr.log").write_text(result.stderr,encoding="utf8")
if {name:hashlib.sha256((run/name).read_bytes()).hexdigest() for name in names}!=before:raise SystemExit("execution mutated archived inputs")
inv=json.loads((run/"inventory.json").read_text())
report={"run_id":a.run_id,"started_at":start,"finished_at":datetime.datetime.now(datetime.timezone.utc).isoformat(),"inputs":before,"expected_hosts":sorted(inv["all"]["children"]["managed"]["hosts"]),"returncode":result.returncode,"command":args}
(run/"report.json").write_text(json.dumps(report,sort_keys=True,indent=2),encoding="utf8")
raise SystemExit(0)

